# Refresh work/evidence-manifest.json. Read-only except for that file.
# Do not edit this file after it has run. Do not edit manifest_s8.py.
import hashlib
import json
import sys
from pathlib import Path

ROOT = Path('.').resolve()


def rel(path):
    path = Path(path).resolve()
    try:
        return path.relative_to(ROOT).as_posix()
    except ValueError:
        return path.as_posix()


def sha(path):
    h = hashlib.sha256()
    data = Path(path).read_bytes()
    h.update(data)
    return h.hexdigest(), len(data)


def add(bucket, path, seen):
    path = Path(path)
    if not path.is_file():
        return
    key = str(path.resolve()).lower()
    if key in seen:
        return
    digest, size = sha(path)
    seen.add(key)
    bucket.append({'path': rel(path), 'sha256': digest, 'bytes': size})


inputs = []
sources = []
outputs = []
seen_in, seen_src, seen_out = set(), set(), set()
for name in [
    'brief.md', 'TASK.md',
    'inputs/00_0100_50000020.decoded.bin',
    'inputs/02_0106_458c0020.decoded.bin',
    'om-emu/unpacked/E147/OLY_E_147_1100_0000_0000.BIN.blk00000000.OE.0100.bin',
]:
    add(inputs, ROOT / name, seen_in)

for path in sorted((ROOT / 'work' / 'scripts').glob('*')):
    if path.is_file():
        add(sources, path, seen_src)
for imports in sorted((ROOT / 'work' / 'out').glob('*-imports.json')):
    rows = json.loads(imports.read_text(encoding='utf-8'))
    for row in rows:
        add(sources, row['path'], seen_src)

add(outputs, ROOT / 'work' / 'result.md', seen_out)
for path in sorted((ROOT / 'work' / 'out').rglob('*')):
    if path.is_file():
        add(outputs, path, seen_out)

commands = []
cmd_dir = ROOT / 'work' / 'out' / 'cmd'
for exit_path in sorted(cmd_dir.glob('*.exit')):
    record = json.loads(exit_path.read_text(encoding='utf-8'))
    nn = exit_path.name[:-5]
    requested = ''
    cmd_txt = cmd_dir / (nn + '.cmd.txt')
    if cmd_txt.is_file():
        for line in cmd_txt.read_text(encoding='utf-8').splitlines():
            if line.startswith('requested: '):
                requested = line[len('requested: '):]
    commands.append({
        'n': nn,
        'requested': requested,
        'status': record.get('status'),
        'start': record.get('start'),
        'end': record.get('end'),
        'scripts': record.get('scripts', []),
        'wrapper_sha256': record.get('wrapper_sha256'),
    })

brief_sha = next(row['sha256'] for row in inputs if row['path'] == 'brief.md')
manifest = {
    'task': 'T7',
    'brief_sha256': brief_sha,
    'inputs': inputs,
    'sources': sources,
    'outputs': outputs,
    'commands': commands,
    'tool_versions': {
        'node': 'v26.12.1',
        'python': sys.version.split()[0],
        'ghidra': '12.2_PUBLIC',
    },
    'note': 'Lists the inputs, sources, and outputs that existed when this script ran, except this manifest. Command 13 .out, .err, and .exit are included; manifest_s8.py omitted them and omitted command 13 from commands. This script\'s own .out, .err, and .exit are written by the wrapper after the script returns, so they are not in this file. om-emu was not modified.',
}
out = ROOT / 'work' / 'evidence-manifest.json'
out.write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
print(f'inputs {len(inputs)} sources {len(sources)} outputs {len(outputs)} commands {len(commands)}')
